// missing by a scan, and helm was reported missing by the dashboard although no
// setting asked for it. Everything now reads these two tables.

// ToolID names one scanner. The values are the configuration's own keys.
type ToolID string

const (
	ToolTrivy       ToolID = config.ToolTrivy
	ToolGitleaks    ToolID = config.ToolGitleaks
	ToolPlumber     ToolID = config.ToolPlumber
	ToolKubeconform ToolID = config.ToolKubeconform
	ToolHelm        ToolID = config.ToolHelm
	ToolKustomize   ToolID = config.ToolKustomize
)

// Tool is what DevDesk knows about one scanner, whatever it is configured with.
type Tool struct {
	ID ToolID
	// Name is how the tool is written for a person — and what they type to
	// install it.
	Name string
	// Binary is the executable's name on PATH.
	Binary       string
	DefaultImage string
	// VersionArgs make the tool print its version on stdout.
	VersionArgs []string
	// HasConfig is a tool DevDesk hands a rules file to (tools.<id>.config).
	HasConfig bool
	// Lost is what a scan did not do because the tool is missing, for the error
	// that says so.
	Lost string
	// ReservedArgs are the flags DevDesk sets itself: the output format and
	// destination it parses, the scanners and server it picks, the rules file
	// it mounts. One of them in tools.<id>.args would break the parsing or
	// contradict a setting, so the configuration view refuses it, by name.
	ReservedArgs []string
}

// CheckArgs refuses extra arguments that name a flag DevDesk sets itself,
// naming the first one — `--format` and `--format=json` alike.
func (t Tool) CheckArgs(args []string) error {
	for _, arg := range args {
		name, _, _ := strings.Cut(arg, "=")
		if slices.Contains(t.ReservedArgs, name) {
			return fmt.Errorf("%s is set by DevDesk and cannot be passed to %s", name, t.Binary)
		}
	}
	return nil
}

